737	// removeLineContaining 删除文本中包含子串的整行（含行尾换行）。
738	func removeLineContaining(s, substr string) string {
739		idx := strings.Index(s, substr)
740		if idx < 0 {
741			return s
742		}
743		start := strings.LastIndex(s[:idx], "\n") + 1
744		end := strings.Index(s[idx:], "\n")
745		if end < 0 {
746			return s[:start]
747		}
748		return s[:start] + s[idx+end+1:]
749	}
