1131	// dupKeyInject 在 balances 对象里注入一个重复键。
1132	func dupKeyInject(good []byte) []byte {
1133		s := string(good)
1134		marker := "\"balances\": {"
1135		idx := strings.Index(s, marker)
1136		if idx < 0 {
1137			// 空 balances 被渲染成 {}，改为含重复键的对象。
1138			s = strings.Replace(s, "\"balances\": {}", "\"balances\": {\"x\": 1, \"x\": 2}", 1)
1139			return []byte(s)
1140		}
1141		insertAt := idx + len(marker)
1142		return []byte(s[:insertAt] + "\"dup\": 1, " + s[insertAt:])
1143	}
