2153		if p, ok, _ := store.Proposal("gip-1"); !ok || p.State != "executed" {
2154			t.Fatalf("proposal state = %+v ok=%v", p, ok)
2155		}
2156		if bal, _ := store.TreasuryBalance(); bal != 745 {
2157			t.Fatalf("treasury = %d, want 745", bal)
2158		}
2159		receipt, ok, err := store.Receipt("gip-1")
2160		if err != nil || !ok || receipt.ExecutedAt != 100 {
2161			t.Fatalf("receipt = %+v ok=%v err=%v", receipt, ok, err)
2162		}
2163	
2164		// 返回的记录是副本：调用方改写不影响状态文件中的记录。
2165		record.State = "mutated"
2166		record.Actions[0] = "mutated"
2167		if p, _, _ := store.Proposal("gip-1"); p.State != "executed" || p.Actions[0] != "transfer:audits:250" {
2168			t.Fatalf("stored record was mutated through returned copy: %+v", p)
2169		}
