2172	// TestRegisterRetryVersusExecuteRace：相同内容的登记重试与首次执行同时发生时，
2173	// 响应按两者实际确认的先后反映状态——登记先确认返回 passed，执行先完成返回
2174	// executed；无论哪种结果，字段都必须来自同一条被认可的记录，且重试不产生
2175	// 二次资金变动。
2176	func TestRegisterRetryVersusExecuteRace(t *testing.T) {
2177		store, _ := openTempStore(t, 100000)
2178		defer store.Close()
2179		mustRegister(t, store, "gip-race", 0, "transfer:a:1")
2180	
2181		const n = 64
2182		states := make([]string, n)
2183		existedFlags := make([]bool, n)
2184		var wg sync.WaitGroup
2185		for i := 0; i < n; i++ {
2186			wg.Add(2)
2187			go func(i int) {
2188				defer wg.Done()
2189				record, existed, err := store.RegisterProposal("gip-race", 0, []string{"transfer:a:1"})
2190				if err != nil || !existed {
2191					t.Errorf("retry existed=%v err=%v", existed, err)
2192					return
2193				}
2194				if record.ID != "gip-race" || record.TimelockEnd != 0 ||
2195					!sameActions(record.Actions, []string{"transfer:a:1"}) {
2196					t.Errorf("retry record = %+v", record)
2197					return
2198				}
2199				states[i] = record.State
2200				existedFlags[i] = existed
2201			}(i)
2202			go func() {
2203				defer wg.Done()
2204				_, _ = store.Execute("gip-race", 0)
2205			}()
2206		}
2207		wg.Wait()
2208	
2209		for i, state := range states {
2210			if state != "passed" && state != "executed" {
2211				t.Fatalf("retry %d reported state=%q", i, state)
2212			}
2213			if !existedFlags[i] {
2214				t.Fatalf("retry %d lost existed flag", i)
2215			}
2216		}
2217		// 全部重试结束后提案已执行，资金只扣减一次。
2218		if p, _, _ := store.Proposal("gip-race"); p.State != "executed" {
2219			t.Fatalf("final state = %s", p.State)
2220		}
2221		if bal, _ := store.TreasuryBalance(); bal != 100000-1 {
2222			t.Fatalf("treasury = %d, want %d", bal, 100000-1)
2223		}
2224		if receipts, _ := store.Receipts(); len(receipts) != 1 {
2225			t.Fatalf("receipts = %d, want 1", len(receipts))
2226		}
2227	}
