12	// 本文件为“多个独立命令进程同时创建同编号投票提案”补充回归保障，保护
13	// “一个编号只保存一份完整定义”的既有规则：无论哪个请求先完成，结果都必须
14	// 与按某种先后顺序串行完成一致——不能多个请求都声称首次创建成功，也不能
15	// 由后提交者覆盖已有定义。串行化由进程内互斥锁与 flock 共同保证，
16	// 因此这些用例直接启动多个 CLI 进程压跨进程路径。
17	
18	// createVoteCLIResponse 是 create-vote --json 的成功结果：既有提案对象与
19	// already_exists 标志都必须保留，冲突不得被包装成一次成功重试。
20	type createVoteCLIResponse struct {
21		Proposal *VoteProposalView `json:"proposal"`
22		Existed  bool              `json:"already_exists"`
23	}
24	
25	// createConcResult 记录一个并发创建进程的全部可观察结果。
26	type createConcResult struct {
27		group       string // 仅动作次序冲突用例使用："A" / "B"
28		code        int
29		stdout      string
30		stderr      string
31		memberOrder []string // 该请求自己提交的成员编号顺序
32		resp        *createVoteCLIResponse
33	}
34	
35	// concCreateRoster 与 concMemberExpectations 描述两个用例共用的名单：
36	// alice、bob、carol、dave，原始权重 300/200/100/400，总权重 1000；
37	// 委托 bob -> carol -> alice 是一条经过两次转交的链，查询时必须展示完整
38	// 路径（含中间成员 carol）与正确的最终代表，不能因输入排列不同而漏掉 carol。
39	var concCreateRoster = []string{"alice:300", "bob:200", "carol:100", "dave:400"}
40	
41	type concMemberExpectation struct {
42		weight   int64
43		path     []string
44		delegate string // 最终代表
45		direct   string // 直接委托对象；未委托为空串
46	}
47	
48	var concMemberExpectations = map[string]concMemberExpectation{
49		"alice": {weight: 300, path: []string{"alice"}, delegate: "alice"},
50		"bob":   {weight: 200, path: []string{"bob", "carol", "alice"}, delegate: "alice", direct: "carol"},
51		"carol": {weight: 100, path: []string{"carol", "alice"}, delegate: "alice", direct: "alice"},
52		"dave":  {weight: 400, path: []string{"dave"}, delegate: "dave"},
53	}
54	
55	// concMemberPerm 生成确定性的成员排列：旋转与反向旋转交替，使并发请求采用
56	// 互不相同的成员排列；排列只影响展示顺序，不影响内容相等性。
57	func concMemberPerm(i int) []string {
58		n := len(concCreateRoster)
59		out := make([]string, n)
60		for j := range concCreateRoster {
61			out[j] = concCreateRoster[(j+i)%n]
62		}
63		if i%2 == 1 {
64			for j, k := 0, n-1; j < k; j, k = j+1, k-1 {
65				out[j], out[k] = out[k], out[j]
66			}
67		}
68		return out
69	}
70	
71	// concDelegationPerm 让委托参数也采用不同排列先后：两条委托的输入次序
72	// 不影响同一项委托关系的含义。
73	func concDelegationPerm(i int) []string {
74		d := []string{"bob:carol", "carol:alice"}
75		if i%2 == 0 {
76			return []string{d[1], d[0]}
77		}
78		return d
79	}
80	
81	func concMemberIDs(members []string) []string {
82		ids := make([]string, len(members))
83		for i, m := range members {
84			ids[i] = m[:strings.LastIndex(m, ":")]
85		}
86		return ids
87	}
88	
89	// concCreateVoteArgs 构造一次 create-vote --json 调用的完整参数。
90	// 治理规则在两个用例间固定：quorum=600、voting=[100,200)、timelock=300。
91	func concCreateVoteArgs(id string, members, delegates, actions []string) []string {
92		args := []string{"create-vote", "--id", id}
93		for _, m := range members {
94			args = append(args, "--member", m)
95		}
96		for _, d := range delegates {
97			args = append(args, "--delegate", d)
98		}
99		args = append(args, "--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300")
100		for _, a := range actions {
101			args = append(args, "--action", a)
102		}
103		return append(args, "--json")
104	}
105	
106	// runConcurrentCreates 用同一个启动栅栏同时放出 n 个独立创建进程，
107	// 每个进程采用不同的成员排列与委托排列，动作由 actionsFor(i) 决定。
108	func runConcurrentCreates(t *testing.T, binary, state, id string, n int, actionsFor func(i int) []string) []createConcResult {
109		t.Helper()
110		results := make([]createConcResult, n)
111		var wg sync.WaitGroup
112		start := make(chan struct{})
113		for i := 0; i < n; i++ {
114			wg.Add(1)
115			go func(i int) {
116				defer wg.Done()
117				members := concMemberPerm(i)
118				args := concCreateVoteArgs(id, members, concDelegationPerm(i), actionsFor(i))
119				<-start
120				so, se, code := runCLI(t, binary, state, args...)
121				results[i] = createConcResult{
122					code:        code,
123					stdout:      so,
124					stderr:      se,
125					memberOrder: concMemberIDs(members),
126				}
127			}(i)
128		}
129		close(start)
130		wg.Wait()
131		return results
132	}
133	
134	// assertSavedConcProposal 核对胜出的保存版本：仍在投票状态、票据为空且无计票
135	// 结论；成员编号与原始权重、委托关系（含两次转交的完整路径与最终代表）、
136	// 法定人数、投票窗口、时间锁、总权重与有序动作全部符合本次共同提交的定义。
137	// wantMemberOrder 非空时还要求成员展示次序就是该顺序（首次创建者的排列）。
138	func assertSavedConcProposal(t *testing.T, v *VoteProposalView, id string, wantActions, wantMemberOrder []string) {
139		t.Helper()
140		if v == nil {
141			t.Fatal("saved proposal view is nil")
142		}
143		if v.ID != id || v.Source != "vote" || v.State != "voting" {
144			t.Fatalf("saved proposal id=%q source=%q state=%q, want %q/vote/voting", v.ID, v.Source, v.State, id)
145		}
146		if v.Quorum != 600 || v.StartAt != 100 || v.Deadline != 200 || v.TimelockEnd != 300 {
147			t.Fatalf("governance rules changed: quorum=%d window=[%d,%d) timelock=%d",
148				v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd)
149		}
150		if v.TotalWeight != 1000 {
151			t.Fatalf("total_weight=%d, want 1000", v.TotalWeight)
152		}
153		if !reflect.DeepEqual(v.Actions, wantActions) {
154			t.Fatalf("actions=%v, want %v in order", v.Actions, wantActions)
155		}
156		if len(v.Ballots) != 0 {
157			t.Fatalf("fresh voting proposal must have empty ballots, got %d: %+v", len(v.Ballots), v.Ballots)
158		}
159		if v.Tally != nil {
160			t.Fatalf("fresh voting proposal must have no tally conclusion, got %+v", v.Tally)
161		}
162		if len(v.Members) != len(concMemberExpectations) {
163			t.Fatalf("member count=%d, want %d", len(v.Members), len(concMemberExpectations))
164		}
165		gotOrder := make([]string, 0, len(v.Members))
166		for _, m := range v.Members {
167			gotOrder = append(gotOrder, m.ID)
168			want, ok := concMemberExpectations[m.ID]
169			if !ok {
170				t.Fatalf("unexpected member %q in saved proposal", m.ID)
171			}
172			if m.Weight != want.weight {
173				t.Fatalf("member %s weight=%d, want %d", m.ID, m.Weight, want.weight)
174			}
175			if m.Delegate != want.delegate {
176				t.Fatalf("member %s final representative=%q, want %q", m.ID, m.Delegate, want.delegate)
177			}
178			if m.Direct != want.direct {
179				t.Fatalf("member %s direct_to=%q, want %q", m.ID, m.Direct, want.direct)
180			}
181			if !reflect.DeepEqual(m.Path, want.path) {
182				t.Fatalf("member %s delegation path=%v, want %v (intermediate hop must not be lost)",
183					m.ID, m.Path, want.path)
184			}
185		}
186		if wantMemberOrder != nil && !reflect.DeepEqual(gotOrder, wantMemberOrder) {
187			t.Fatalf("member display order=%v, must preserve first creator's order %v; reordered retries must not rewrite it",
188				gotOrder, wantMemberOrder)
189		}
190	}
191	
192	// assertNoTreasuryChange 核对创建并发结束后资金库余额、账户余额与执行凭据
193	// 全部保持创建前的值：创建只登记提案，绝不转账、不产生凭据。
194	func assertNoTreasuryChange(t *testing.T, binary, state string, initial int64) {
195		t.Helper()
196		bo, be, code := runCLI(t, binary, state, "balances", "--json")
197		if code != 0 {
198			t.Fatalf("balances query failed: %s", be)
199		}
200		var bal struct {
201			Treasury int64            `json:"treasury"`
202			Balances map[string]int64 `json:"balances"`
203		}
204		if err := json.Unmarshal([]byte(bo), &bal); err != nil {
205			t.Fatalf("balances output is not JSON: %v\n%s", err, bo)
206		}
207		if bal.Treasury != initial {
208			t.Fatalf("treasury balance=%d, must stay %d", bal.Treasury, initial)
209		}
210		if len(bal.Balances) != 0 {
211			t.Fatalf("no transfers may happen at create time, got balances %v", bal.Balances)
212		}
213		ro, re, code := runCLI(t, binary, state, "receipts", "--json")
214		if code != 0 {
215			t.Fatalf("receipts query failed: %s", re)
216		}
217		var receipts []json.RawMessage
218		if err := json.Unmarshal([]byte(ro), &receipts); err != nil {
219			t.Fatalf("receipts output is not JSON: %v\n%s", err, ro)
220		}
221		if len(receipts) != 0 {
222			t.Fatalf("create must produce no execution receipts, got %d", len(receipts))
223		}
224	}
