166	func runInit(args []string) {
167		cf := newCmdFlags("init")
168		balanceRaw := cf.fs.String("balance", "", "initial treasury balance (non-negative int64)")
169		cf.parse(args)
170		balance := parseIntFlag(cf.fs, "balance", *balanceRaw)
171	
172		store, err := govflow.InitTreasury(cf.state, balance)
173		if err != nil {
174			fail(err)
175		}
176		defer store.Close()
177		if cf.asJSON {
178			emitJSON(map[string]any{"state": cf.state, "treasury": balance, "initialized": true})
179			return
180		}
181		fmt.Printf("initialized %s with treasury balance %d\n", cf.state, balance)
182	}
183	
184	func runRegister(args []string) {
185		cf := newCmdFlags("register")
186		id := cf.fs.String("id", "", "proposal id (non-empty)")
187		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
188		var actions actionList
189		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
190		cf.parse(args)
191		if *id == "" {
192			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
193			os.Exit(2)
194		}
195		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
196	
197		store, err := govflow.Open(cf.state)
198		if err != nil {
199			fail(err)
200		}
201		defer store.Close()
202		// 响应字段一律取这次登记实际认可的记录：首次登记为 passed；相同内容重试
203		// 保留已有记录的实际状态（passed 或 executed），已执行的提案不得报成 passed。
204		record, existed, err := store.RegisterProposal(*id, timelock, []string(actions))
205		if err != nil {
206			fail(err)
207		}
208		if cf.asJSON {
209			emitJSON(map[string]any{"id": record.ID, "state": record.State, "timelock_end": record.TimelockEnd,
210				"actions": record.Actions, "already_registered": existed})
211			return
212		}
213		if existed {
214			fmt.Printf("proposal %s already registered with identical content (state=%s)\n", record.ID, record.State)
215		} else {
216			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", record.ID, len(record.Actions), record.TimelockEnd)
217		}
218	}
219	
220	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
221	type memberList []govflow.VoteMember
222	
223	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
224	func (m *memberList) Set(v string) error {
225		id, weight, err := splitMember(v)
226		if err != nil {
227			return err
228		}
229		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
230		return nil
231	}
232	
233	func splitMember(raw string) (string, int64, error) {
234		idx := strings.LastIndex(raw, ":")
235		if idx <= 0 || idx == len(raw)-1 {
236			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
237		}
238		id := raw[:idx]
239		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
240		if err != nil {
241			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
242		}
243		return id, weight, nil
244	}
245	
246	// delegationList 收集重复的 --delegate FROM:TO 参数原文，保持提交顺序。
247	// 成员编号本身可含冒号（如 team:alice），FROM 与 TO 两端都可能含冒号，
248	// 因此不能在解析单个参数时切分：必须等完整成员名单齐备后，
249	// 由 resolveDelegations 结合名单确定唯一的切分点。
250	type delegationList []string
251	
252	func (d *delegationList) String() string { return fmt.Sprint([]string(*d)) }
253	func (d *delegationList) Set(v string) error {
254		*d = append(*d, v)
255		return nil
256	}
257	
258	// delegationUsageError 是 --delegate 的参数错误（格式错误或切分有歧义），
259	// 以退出码 2 结束；格式正确但无法匹配名单的错误不属于此类，按域错误退出码 1 处理。
260	type delegationUsageError struct{ reason string }
261	
262	func (e *delegationUsageError) Error() string { return e.reason }
263	
264	// resolveDelegations 结合本次提交的完整成员名单理解每条 FROM:TO 委托原文。
265	// 成员编号保持原文并区分大小写；编号可含冒号，且冒号可以出现在编号开头、
266	// 末尾或连续出现（如 ":alice"、"a:"、"a::b"），所以一条委托原文在每个冒号
267	// 位置都有一种候选切分，切分点两侧的编号仍须各自非空。
268	//
269	// 判定只依据“两端非空”这一纯语法条件与成员名单，不拿自委托/重复/循环等
270	// 业务规则替用户筛选候选：
271	//   - 原文不含冒号，或每个冒号位置的切分都会让某一端为空（如 ":alice"、
272	//     "alice:"、":"、"::"：冒号只出现在首尾、中间再无切分点）：格式错误，
273	//     参数错误（退出码 2）；
274	//   - 存在两端非空的切分，但没有任何一对都在名单里：域错误（退出码 1）；
275	//   - 两对或更多成员同时命中（即使其中某种解释随后会触发自委托、重复或循环）：
276	//     委托有歧义，参数错误（退出码 2），错误列出有歧义的原文与全部成员对；
277	//   - 恰好一对命中：按该对成员创建委托。
278	//
279	// 成员与委托参数在命令行上的排列先后不影响结果：解析前名单已收集完毕。
280	func resolveDelegations(members []govflow.VoteMember, raws []string) ([]govflow.Delegation, error) {
281		roster := make(map[string]bool, len(members))
282		for _, m := range members {
283			roster[m.ID] = true
284		}
285		out := make([]govflow.Delegation, 0, len(raws))
286		for _, raw := range raws {
287			var matches []govflow.Delegation
288			hasNonEmptySplit := false
289			for i := 0; i < len(raw); i++ {
290				if raw[i] != ':' {
291					continue
292				}
293				from, to := raw[:i], raw[i+1:]
294				// 纯语法候选：切分点两侧都非空才算“存在 FROM:TO 写法”。
295				// 编号本身允许以冒号开头、结尾或包含连续冒号，因此位于位置 0
296				// 的冒号产生的空 from、以及结尾冒号产生的空 to 都只是不合法的
297				// 切分点之一，绝不据此提前拒绝整条原文——其他冒号位置仍可能合法。
298				if from == "" || to == "" {
299					continue
300				}
301				hasNonEmptySplit = true
302				if roster[from] && roster[to] {
303					matches = append(matches, govflow.Delegation{From: from, To: to})
304				}
305			}
306			if !hasNonEmptySplit {
307				return nil, &delegationUsageError{fmt.Sprintf("malformed delegation %q, expected FROM:TO with non-empty member ids on both sides", raw)}
308			}
309			switch len(matches) {
310			case 0:
311				return nil, fmt.Errorf("delegation %q does not match any pair of members on the roster", raw)
312			case 1:
313				out = append(out, matches[0])
314			default:
315				pairs := make([]string, len(matches))
316				for i, m := range matches {
317					pairs[i] = fmt.Sprintf("%q delegating to %q", m.From, m.To)
318				}
319				return nil, &delegationUsageError{fmt.Sprintf("ambiguous delegation %q: could mean %s",
320					raw, strings.Join(pairs, " or "))}
321			}
322		}
323		return out, nil
324	}
325	
326	func runCreateVote(args []string) {
327		cf := newCmdFlags("create-vote")
328		id := cf.fs.String("id", "", "proposal id (non-empty)")
329		var members memberList
330		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
331		var delegationRaws delegationList
332		cf.fs.Var(&delegationRaws, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality; either side may itself contain colons and is matched against the full member roster)")
333		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
334		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
335		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
336		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
337		var actions actionList
338		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
339		cf.parse(args)
340		if *id == "" {
341			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
342			os.Exit(2)
343		}
344		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
345		start := parseIntFlag(cf.fs, "start", *startRaw)
346		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
347		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
348		if len(members) == 0 {
349			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
350			os.Exit(2)
351		}
352		// 委托切分依赖完整成员名单，必须在打开状态文件之前完成：
353		// 格式错误与歧义是参数错误（退出码 2），无法匹配名单是域错误（退出码 1），
354		// 两种失败都不触碰已有状态文件。
355		delegations, derr := resolveDelegations([]govflow.VoteMember(members), []string(delegationRaws))
356		if derr != nil {
357			var usageErr *delegationUsageError
358			if errors.As(derr, &usageErr) {
359				fmt.Fprintf(os.Stderr, "usage error: %v\n", derr)
360				os.Exit(2)
361			}
362			fail(derr)
363		}
364	
365		store, err := govflow.Open(cf.state)
366		if err != nil {
367			fail(err)
368		}
369		defer store.Close()
370		in := &govflow.CreateVoteInput{
371			ID:          *id,
372			Members:     []govflow.VoteMember(members),
373			Delegations: delegations,
374			Quorum:      quorum,
375			StartAt:     start,
376			Deadline:    deadline,
377			TimelockEnd: timelock,
378			Actions:     []string(actions),
379		}
380		view, existed, err := store.CreateVoteProposal(in)
381		if err != nil {
382			fail(err)
383		}
384		if cf.asJSON {
385			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
386			return
387		}
388		if existed {
389			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
390		} else {
391			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
392				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
393		}
394	}
395	
396	func runVote(args []string) {
397		cf := newCmdFlags("vote")
398		id := cf.fs.String("id", "", "proposal id to vote on")
399		voter := cf.fs.String("voter", "", "voting member (must be a final representative)")
400		choice := cf.fs.String("choice", "", "vote choice: for or against")
401		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
402		cf.parse(args)
403		if *id == "" || *voter == "" {
404			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
405			os.Exit(2)
406		}
407		var support bool
408		switch *choice {
409		case "for":
410			support = true
411		case "against":
412			support = false
413		default:
414			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
415			os.Exit(2)
416		}
417		now := parseIntFlag(cf.fs, "now", *nowRaw)
418	
419		store, err := govflow.Open(cf.state)
420		if err != nil {
421			fail(err)
422		}
423		defer store.Close()
424		ballot, err := store.CastVote(*id, *voter, support, now)
425		if err != nil {
426			fail(err)
427		}
428		if cf.asJSON {
429			emitJSON(ballot)
430			return
431		}
432		fmt.Printf("recorded vote proposal=%s representative=%s choice=%s weight=%d voted_at=%d\n",
433			*id, ballot.Representative, choiceWord(ballot.Support), ballot.Weight, ballot.VotedAt)
434	}
435	
436	func choiceWord(support bool) string {
437		if support {
438			return "for"
439		}
440		return "against"
441	}
