// TestConcurrentInitZeroBalance：初始余额为 0 是合法成功，零不能被误认为
// “初始化尚未完成”：并发请求中仍恰好一次成功，胜者状态可立即打开使用，
// 落盘文件把两个余额字段都明确写成 0，后续重新打开仍是余额 0 的完整状态。
func TestConcurrentInitZeroBalance(t *testing.T) {
